{
  "schemaVersion": 1,
  "id": "parker.bar-drawer",
  "name": "Bar drawer",
  "version": "1.0.0",
  "author": "parker",
  "description": "A drawer button that opens a panel holding the bar widgets you tucked away",
  "kinds": [
    "bar-widget"
  ],
  "entryPoints": {
    "barWidget": "Drawer.qml"
  },
  "barWidget": {
    "displayName": "Bar drawer",
    "description": "Click to open a panel holding the widgets listed in this entry's \"items\"",
    "category": "Layout",
    "allowMultiple": true,
    "defaultSection": "right",
    "defaults": {
      "items": [],
      "autoClose": true,
      "autoCloseDelay": 900
    },
    "schema": [
      { "key": "icon", "type": "string", "label": "Button icon", "defaultValue": "", "description": "Optional glyph. Empty uses a chevron that points toward the drawer." },
      { "key": "autoClose", "type": "boolean", "label": "Close when the pointer leaves", "defaultValue": true },
      { "key": "autoCloseDelay", "type": "integer", "label": "Auto-close delay (ms)", "min": 200, "max": 10000, "step": 100, "defaultValue": 900 }
    ]
  }
}

import QtQuick
import qs.Commons

// The `bar` object handed to a widget that lives inside the drawer. It mirrors
// the bar facade the drawer itself received and forwards every call to it, with
// two changes:
//   - requestPopout() tells the drawer that the request comes from one of its
//     own widgets, so the drawer stays open while that widget's panel is up;
//   - moduleWidgets() returns the drawer's live instances of the widget (the
//     host only knows widgets that sit directly in the bar).
QtObject {
  id: proxy

  property var host: null
  property var drawer: null
  property var drawerWindow: null
  property string moduleId: ""

  property color foreground: host ? host.foreground : Color.bar.text
  property color barForeground: host ? host.barForeground : Color.bar.text
  property color background: host ? host.background : Color.bar.background
  property color urgent: host ? host.urgent : Color.urgent
  property string fontFamily: host ? host.fontFamily : Style.font.family
  property string position: host ? host.position : "top"
  property bool vertical: host ? host.vertical : false
  property int barSize: host ? host.barSize : Style.bar.sizeHorizontal
  property bool transparent: false
  property bool foregroundAnimationEnabled: host ? host.foregroundAnimationEnabled !== false : true
  property bool centerSectionRevealHeld: false
  property bool centerHoverRevealSuppressed: host ? host.centerHoverRevealSuppressed === true : false
  property var shell: host ? host.shell : null
  property var activePopout: host ? host.activePopout : null
  property var clickTargets: host && host.clickTargets ? host.clickTargets : []
  property var layoutConfig: host && host.layoutConfig ? host.layoutConfig : ({})
  property var foreignPopoutMarker: host ? host.foreignPopoutMarker : null

  function run(command) { if (host) host.run(command) }
  function shellQuote(value) { return Util.shellQuote(value) }
  function showTooltip(target, text) { if (host) host.showTooltip(target, text) }
  function hideTooltip(target) { if (host) host.hideTooltip(target) }
  function registerClickTarget(target) { if (host && host.registerClickTarget) host.registerClickTarget(target) }
  function unregisterClickTarget(target) { if (host && host.unregisterClickTarget) host.unregisterClickTarget(target) }

  function requestPopout(owner) {
    if (!host) return
    if (drawer) drawer.beginNestedPopout(owner)
    host.requestPopout(owner)
    if (drawer) drawer.endNestedPopout()
  }

  function releasePopout(owner) { if (host) host.releasePopout(owner) }
  function switchPanelFrom(owner, direction) { return false }

  function targetBelongsToWindow(target, window) {
    return host && host.targetBelongsToWindow ? host.targetBelongsToWindow(target, window) : false
  }

  function moduleWidgets(id) {
    if (String(id || "") !== moduleId || !drawerWindow) return []
    return drawerWindow.widgetsFor(moduleId)
  }

  function setCenterHoverRevealSuppressed(value) {
    if (host && host.setCenterHoverRevealSuppressed) host.setCenterHoverRevealSuppressed(value)
  }
}

import QtQuick
import Quickshell
import Quickshell.Wayland
import qs.Commons
import qs.Ui

// The drawer panel. A transparent layer-shell strip anchored to the same screen
// edge as the bar, spanning the bar plus the card below it. Only the card takes
// input (see `mask`), so the bar underneath stays clickable. Covering the bar's
// strip matters for the tucked widgets' own panels: they place themselves just
// past the edge of the window their button lives in, so with this geometry they
// open beyond the drawer instead of on top of it.
PanelWindow {
  id: win

  property var drawer: null
  property Item anchorItem: null
  property var entries: []

  readonly property var hostBar: drawer ? drawer.bar : null
  readonly property bool open: drawer ? drawer.opened === true : false
  readonly property string barPos: hostBar ? String(hostBar.position || "top") : "top"
  readonly property bool vertical: barPos === "left" || barPos === "right"
  readonly property int slotSize: hostBar && hostBar.barSize ? hostBar.barSize : Style.bar.sizeHorizontal
  readonly property var anchorWindow: anchorItem ? anchorItem.QsWindow.window : null
  readonly property real barThickness: anchorWindow
    ? (vertical ? anchorWindow.width : anchorWindow.height) : slotSize
  readonly property int gap: Style.gapsOut
  readonly property int edgeMargin: Style.gapsOut
  readonly property bool hovered: cardHover.hovered
  readonly property Item contentRoot: card
  readonly property bool empty: vertical ? widgetGrid.implicitHeight <= 0 : widgetGrid.implicitWidth <= 0

  function widgetsFor(id) {
    var out = []
    for (var i = 0; i < repeater.count; i++) {
      var slot = repeater.itemAt(i)
      if (slot && slot.widget && slot.entryId === id) out.push(slot.widget)
    }
    return out
  }

  function allWidgets() {
    var out = []
    for (var i = 0; i < repeater.count; i++) {
      var slot = repeater.itemAt(i)
      if (slot && slot.widget) out.push(slot.widget)
    }
    return out
  }

  screen: anchorWindow ? anchorWindow.screen : null
  visible: open || card.opacity > 0
  color: "transparent"
  exclusionMode: ExclusionMode.Ignore
  WlrLayershell.namespace: "parker-bar-drawer"
  WlrLayershell.layer: WlrLayer.Top
  WlrLayershell.keyboardFocus: WlrKeyboardFocus.None

  anchors {
    top: win.barPos !== "bottom"
    bottom: win.barPos !== "top"
    left: win.barPos !== "right"
    right: win.barPos !== "left"
  }

  implicitWidth: vertical ? Math.ceil(barThickness + gap + card.width) : 0
  implicitHeight: vertical ? 0 : Math.ceil(barThickness + gap + card.height)

  mask: Region { item: card }

  TransformWatcher {
    id: anchorWatcher
    a: win.anchorWindow ? win.anchorWindow.contentItem : null
    b: win.anchorItem
  }

  readonly property point anchorPos: {
    anchorWatcher.transform
    if (!anchorItem || !anchorWindow || !anchorWindow.contentItem) return Qt.point(0, 0)
    return anchorItem.mapToItem(anchorWindow.contentItem, 0, 0)
  }

  BorderSurface {
    id: card

    readonly property real wantX: win.anchorPos.x + (win.anchorItem ? win.anchorItem.width : 0) / 2 - width / 2
    readonly property real wantY: win.anchorPos.y + (win.anchorItem ? win.anchorItem.height : 0) / 2 - height / 2

    x: win.vertical
      ? (win.barPos === "left" ? win.barThickness + win.gap : 0)
      : Math.round(Math.max(win.edgeMargin, Math.min(wantX, win.width - width - win.edgeMargin)))
    y: win.vertical
      ? Math.round(Math.max(win.edgeMargin, Math.min(wantY, win.height - height - win.edgeMargin)))
      : (win.barPos === "top" ? win.barThickness + win.gap : 0)
    width: Math.ceil((win.empty ? emptyLabel.implicitWidth : widgetGrid.implicitWidth) + contentLeftInset + contentRightInset)
    height: Math.ceil((win.empty ? emptyLabel.implicitHeight : widgetGrid.implicitHeight) + contentTopInset + contentBottomInset)

    color: Color.popups.background
    borderSpec: Border.surfaceSpec("popups", "border", Color.popups.border, Math.max(1, Style.space(2)))
    padding: Style.space(4)
    radius: Style.cornerRadius
    opacity: win.open ? 1.0 : 0

    Behavior on opacity {
      NumberAnimation { duration: 140; easing.type: Easing.OutCubic }
    }

    HoverHandler { id: cardHover }

    Text {
      id: emptyLabel
      visible: win.empty
      x: card.contentLeftInset
      y: card.contentTopInset
      leftPadding: Style.space(8)
      rightPadding: Style.space(8)
      height: win.slotSize
      verticalAlignment: Text.AlignVCenter
      text: win.entries.length > 0 ? "Nothing to show right now" : "Drawer is empty"
      color: Color.muted
      font.family: win.hostBar ? win.hostBar.fontFamily : Style.font.family
      font.pixelSize: Style.font.body
    }

    Grid {
      id: widgetGrid
      x: card.contentLeftInset
      y: card.contentTopInset
      spacing: 0
      columns: win.vertical ? 1 : Math.max(1, repeater.count)

      Repeater {
        id: repeater
        model: win.entries

        Item {
          id: slot

          required property var modelData
          readonly property string entryId: String(modelData.id)
          readonly property Item widget: loader.item

          // Same rule as the bar's own slots: a widget that hides itself
          // (no updates pending, no weather yet, ...) takes no room.
          readonly property bool shown: widget !== null && widget.visible
          width: !shown ? 0 : (win.vertical ? win.slotSize : widget.implicitWidth)
          height: !shown ? 0 : (win.vertical ? widget.implicitHeight : win.slotSize)

          NestedBar {
            id: proxy
            host: win.hostBar
            drawer: win.drawer
            drawerWindow: win
            moduleId: slot.entryId
          }

          function inject() {
            var target = loader.item
            if (!target) return
            if ("bar" in target) target.bar = proxy
            if ("moduleName" in target) target.moduleName = slot.entryId
            if ("settings" in target) target.settings = slot.modelData.settings || ({})
          }

          onModelDataChanged: inject()

          Loader {
            id: loader
            anchors.fill: parent
            source: slot.modelData.url
            onLoaded: {
              slot.inject()
              Qt.callLater(slot.inject)
            }
            onStatusChanged: {
              if (status === Loader.Error)
                console.warn("parker.bar-drawer: could not load " + slot.entryId + " from " + source)
            }
          }
        }
      }
    }
  }
}

import QtQuick
import Quickshell
import Quickshell.Io
import qs.Commons
import qs.Ui

// Bar drawer: a button that opens a panel holding the widgets listed in this
// entry's `items` in ~/.config/omarchy/shell.json, e.g.
//
//   { "id": "parker.bar-drawer",
//     "items": [ "omarchy.weather", { "id": "omarchy.clock", "format": "HH:mm" } ] }
//
// Each item is a widget id, or an object with an id plus that widget's usual
// settings. Move a widget's entry out of bar.layout when you tuck it away, so
// it is not shown twice.
BarWidget {
  id: root

  readonly property string pluginId: "parker.bar-drawer"

  property bool opened: false
  property bool everOpened: false
  property bool engaged: false
  property bool nestedRequestPending: false
  property var nestedOwner: null

  // id -> entry-point URL for every bar widget installed (built-in and user).
  property var catalog: ({})
  property bool catalogReady: false
  property var warned: ({})

  readonly property string barPos: bar ? String(bar.position || "top") : "top"
  readonly property bool autoClose: setting("autoClose", true) !== false
  readonly property int autoCloseDelay: Math.max(200, Number(setting("autoCloseDelay", 900)) || 900)

  // `items` normalised to [{ id, settings }], first occurrence of an id wins.
  readonly property var itemEntries: {
    var raw = setting("items", [])
    var list = Array.isArray(raw) ? raw : []
    var seen = ({})
    var out = []
    for (var i = 0; i < list.length; i++) {
      var item = list[i]
      var id = typeof item === "string" ? item : (Util.isPlainObject(item) ? String(item.id || "") : "")
      if (!id || seen[id]) continue
      if (id === root.pluginId || id === root.moduleName) continue  // no drawer inside a drawer
      seen[id] = true
      var settings = ({})
      if (Util.isPlainObject(item)) {
        for (var key in item) if (key !== "id") settings[key] = item[key]
      }
      out.push({ id: id, settings: settings })
    }
    return out
  }

  readonly property var resolvedEntries: {
    var out = []
    if (!catalogReady) return out
    for (var i = 0; i < itemEntries.length; i++) {
      var url = catalog[itemEntries[i].id]
      if (url) out.push({ id: itemEntries[i].id, settings: itemEntries[i].settings, url: url })
    }
    return out
  }

  readonly property bool pointerInside: buttonHover.hovered
    || (windowLoader.item !== null && windowLoader.item.hovered === true)

  readonly property bool nestedActive: {
    if (!bar || !opened) return false
    var active = bar.activePopout
    return !!active && active !== root && ownsPopout(active)
  }

  function chevron() {
    var custom = String(setting("icon", "") || "")
    if (custom) return custom
    if (barPos === "bottom") return opened ? "\uf078" : "\uf077"
    if (barPos === "left") return opened ? "\uf053" : "\uf054"
    if (barPos === "right") return opened ? "\uf054" : "\uf053"
    return opened ? "\uf077" : "\uf078"
  }

  // ---- open / close, and the bar's one-popup-at-a-time coordinator --------

  function open() {
    if (opened) return
    everOpened = true
    engaged = pointerInside
    opened = true
    if (bar) bar.requestPopout(root)
  }

  function close() {
    if (!opened) return
    opened = false
    engaged = false
    var widgets = windowLoader.item ? windowLoader.item.allWidgets() : []
    for (var i = 0; i < widgets.length; i++) {
      var w = widgets[i]
      if (w && w.opened === true && typeof w.close === "function") w.close()
    }
    nestedOwner = null
    if (bar && bar.activePopout === root) bar.releasePopout(root)
  }

  function toggle() { opened ? close() : open() }

  // Called by the bar when another popup takes over. A tucked widget opening
  // its own panel is not "another popup": keep the drawer up underneath it.
  function closeForPopoutSwitch() {
    if (nestedRequestPending) return
    close()
  }

  function beginNestedPopout(owner) {
    nestedRequestPending = true
    nestedOwner = owner
  }

  function endNestedPopout() {
    nestedRequestPending = false
  }

  // True for this drawer, and for popups that belong to one of its widgets.
  function ownsPopout(target) {
    if (!target) return false
    if (target === root || target === nestedOwner) return true
    var content = windowLoader.item ? windowLoader.item.contentRoot : null
    if (!content) return false
    var node = target
    for (var depth = 0; node && depth < 64; depth++) {
      if (node === content) return true
      node = (node.anchorItem !== undefined && node.anchorItem) ? node.anchorItem
        : (node.parent !== undefined ? node.parent : null)
    }
    return false
  }

  Connections {
    target: root.bar
    ignoreUnknownSignals: true

    function onActivePopoutChanged() {
      if (!root.opened || !root.bar) return
      var active = root.bar.activePopout
      if (!active) {
        // A tucked widget closed its panel: take the coordinator back so the
        // bar keeps showing the drawer as the open popup.
        Qt.callLater(function() {
          if (root.opened && root.bar && !root.bar.activePopout) root.bar.requestPopout(root)
        })
      } else if (!root.nestedRequestPending && !root.ownsPopout(active)) {
        root.close()
      }
    }
  }

  onPointerInsideChanged: if (pointerInside && opened) engaged = true

  // Close after the pointer has been in the drawer and left it, unless one of
  // the tucked widgets has its own panel open. A drawer opened by keyboard or
  // IPC stays until toggled.
  Timer {
    interval: root.autoCloseDelay
    running: root.opened && root.autoClose && root.engaged && !root.pointerInside && !root.nestedActive
    onTriggered: root.close()
  }

  // ---- widget catalogue ----------------------------------------------------

  readonly property string omarchyPath: Quickshell.env("OMARCHY_PATH") || "/usr/share/omarchy"
  readonly property string configHome: Quickshell.env("XDG_CONFIG_HOME") || ((Quickshell.env("HOME") || "") + "/.config")

  function parseCatalog(text) {
    var next = ({})
    var records = String(text || "").split("\x1e")
    for (var i = 0; i < records.length; i++) {
      var sep = records[i].indexOf("\x1f")
      if (sep <= 0) continue
      var path = records[i].slice(0, sep)
      var manifest = null
      try { manifest = JSON.parse(records[i].slice(sep + 1)) } catch (e) { continue }
      if (!Util.isPlainObject(manifest) || !manifest.id) continue
      if (!Array.isArray(manifest.kinds) || manifest.kinds.indexOf("bar-widget") === -1) continue
      var ep = manifest.entryPoints ? manifest.entryPoints.barWidget : ""
      if (typeof ep !== "string" || !ep || ep.charAt(0) === "/" || ep.indexOf("..") !== -1) continue
      var dir = path.slice(0, path.lastIndexOf("/"))
      next[String(manifest.id)] = Util.fileUrl(dir + "/" + ep)
    }
    delete next[root.pluginId]
    catalog = next
    catalogReady = true
    reportProblems()
  }

  function reportProblems() {
    if (!catalogReady) return
    var onBar = ({})
    var layout = bar && bar.layoutConfig ? bar.layoutConfig : ({})
    var sections = ["left", "center", "right"]
    for (var s = 0; s < sections.length; s++) {
      var list = Array.isArray(layout[sections[s]]) ? layout[sections[s]] : []
      for (var j = 0; j < list.length; j++) {
        var id = typeof list[j] === "string" ? list[j] : (list[j] && list[j].id)
        if (id) onBar[id] = true
      }
    }
    var nextWarned = Object.assign({}, warned)
    for (var i = 0; i < itemEntries.length; i++) {
      var itemId = itemEntries[i].id
      var problem = !catalog[itemId] ? "unknown widget id"
        : (onBar[itemId] ? "also placed in bar.layout, so it shows twice" : "")
      var key = itemId + ":" + problem
      if (problem && !nextWarned[key]) {
        console.warn("parker.bar-drawer: " + itemId + ": " + problem)
        nextWarned[key] = true
      }
    }
    warned = nextWarned
  }

  function rescan() {
    if (scanProcess.running) return
    scanProcess.command = ["bash", "-c",
      "emit() { printf '\\036%s\\037' \"$1\"; cat -- \"$1\" 2>/dev/null; }; " +
      "[ -d \"$1\" ] && find \"$1\" -mindepth 2 -maxdepth 3 -type f \\( -name manifest.json -o -name '*.manifest.json' \\) | sort | while IFS= read -r m; do emit \"$m\"; done; " +
      "[ -d \"$2\" ] && find \"$2\" -mindepth 2 -maxdepth 2 -type f -name manifest.json | sort | while IFS= read -r m; do emit \"$m\"; done; " +
      "exit 0",
      "bar-drawer-scan", omarchyPath + "/shell/plugins", configHome + "/omarchy/plugins"]
    scanProcess.running = true
  }

  Process {
    id: scanProcess
    stdout: StdioCollector {
      onStreamFinished: root.parseCatalog(text)
    }
  }

  Component.onCompleted: rescan()

  // A newly installed widget id: look again rather than wait for a reload.
  onItemEntriesChanged: {
    for (var i = 0; i < itemEntries.length; i++) {
      if (catalogReady && !catalog[itemEntries[i].id]) { rescan(); return }
    }
    reportProblems()
  }

  // ---- bar button ------------------------------------------------------------

  implicitWidth: button.implicitWidth
  implicitHeight: button.implicitHeight

  BarIconButton {
    id: button
    anchors.fill: parent
    bar: root.bar
    text: root.chevron()
    active: root.opened
    useActiveColor: false
    tooltipText: root.opened ? "" : (root.itemEntries.length + " tucked away")

    onPressed: function(b) {
      if (b === Qt.LeftButton) root.toggle()
    }
  }

  HoverHandler { id: buttonHover }

  Loader {
    id: windowLoader
    active: root.everOpened
    sourceComponent: Component {
      DrawerWindow {
        drawer: root
        anchorItem: button
        entries: root.resolvedEntries
      }
    }
  }
}

